record ClockEntry(int EmployeeId, double? Hours);

List<ClockEntry> entries = [new(1, 8), new(1, null), new(2, 6)];

double total = entries
    .Where(entry => entry.EmployeeId == 1 && entry.Hours is not null)
    .Select(entry => entry.Hours!.Value)
    .Sum();

Console.WriteLine(total);
